import {esc} from './weather-tools.js';
const $=s=>document.querySelector(s);
async function api(path,body){const r=await fetch('/api/answer-push/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw Error(data.error||'Avvisi non disponibili');return data}
export function notificationPolicyHTML(){return '<div class="notification-policy"><p><strong>Ti inviamo al massimo 2 notifiche al giorno.</strong><br>Nessun invio fra le 22 e le 7, ora italiana. Mai pubblicità.</p><a href="#patto">Il nostro patto</a></div>'}
export function pactPage(){return `<section class="pact-page" aria-labelledby="pact-title"><a href="#profilo">← Profilo</a><h1 id="pact-title">Il nostro patto</h1><p><strong>Nessuna pubblicità. Mai.</strong></p><p><strong>Al massimo due notifiche al giorno.</strong><br>Solo gli avvisi che scegli: risposte, conferme e cambiamenti dei tuoi eventi. Nessun invio fra le 22 e le 7, ora italiana.</p><p><strong>Le previsioni hanno una cronologia.</strong><br>Ti mostriamo quando abbiamo acquisito i dati e cosa è cambiato. Se non abbiamo dati per verificare un errore, lo diciamo.</p><p><strong>Le persone non emettono allerte ufficiali.</strong><br>Le segnalazioni della community restano distinte dai bollettini della Protezione Civile.</p><details class="info-disclosure"><summary>Cosa è disponibile oggi</summary><p>L’ora indicata è quella di acquisizione, non di emissione del modello. La cronologia si aggiorna durante la consultazione, al massimo ogni 15 minuti.</p><p>Il confronto serale riguarda due aggiornamenti del modello: non è ancora un voto sull’accuratezza basato su misure osservate.</p><p>Gli avvisi automatici prima dell’uscita e per le allerte ufficiali non sono ancora disponibili. Per gli eventi, controlliamo i cambiamenti quando qualcuno li apre.</p><p>Il limite giornaliero è condiviso tra i tipi di avviso del tuo profilo. Gli orari indicano l’invio; la consegna dipende dal browser e dalla rete.</p></details><p><a href="#profilo">Scegli i tuoi avvisi</a> · <a href="#informazioni">Fonti e informazioni</a></p></section>`}
export function notificationsHTML(){return `<section id="notification-settings" aria-live="polite"><h2>I tuoi avvisi</h2>${notificationPolicyHTML()}<p>Controllo le preferenze…</p></section>`}
export async function bindNotifications(){const host=$('#notification-settings');if(!host)return;try{const [c,feedback,groups]=await Promise.all([api('config'),api('feedback'),fetch('/api/groups/mine').then(async r=>{if(!r.ok)throw Error();return r.json()})]);if(!host.isConnected)return;
 host.innerHTML=`<h2>I tuoi avvisi</h2>${notificationPolicyHTML()}<p><a href="#insieme">Risposte alle domande sul cielo</a> · <a href="#scuole">Risposte sulle scuole</a></p>${feedback.notices.map(n=>`<p>La tua segnalazione di ${esc(n.city)} è confermata da ${n.confirms} ${n.confirms===1?'persona':'persone'}. Le osservazioni aggiungono informazioni locali; il modello resta distinto. <a href="#community">Apri la community</a></p>`).join('')}<p><a href="#insieme">I miei eventi</a></p>${groups.groups.filter(g=>g.unread).map(g=>`<p>È cambiata la previsione per ${esc(g.name)}. <a href="#evento?id=${encodeURIComponent(g.id)}">Controlla gli orari</a></p>`).join('')}<label><input type="checkbox" id="notify-answers" ${c.enabled?'checked':''}> Risposte alle mie domande</label><label><input type="checkbox" id="notify-feedback" ${c.feedbackEnabled?'checked':''}> Conferme alle mie segnalazioni</label><label><input type="checkbox" id="notify-events" ${c.eventsEnabled?'checked':''}> Cambiamento della previsione dei miei eventi</label><details class="info-disclosure"><summary aria-label="Come funzionano gli avvisi">i</summary><p>Un solo avviso per evento. Il controllo avviene quando qualcuno apre l’evento, non a orari fissi. Avvisi prima dell’uscita e allerte ufficiali automatiche non ancora disponibili: consulta il bollettino nell’app.</p></details><p id="notify-status" role="status"></p>${c.eligible&&c.available?'<button id="notify-save">Salva preferenze avvisi</button>':'<p>Gli avvisi si possono attivare dopo la prima segnalazione, su un browser compatibile.</p>'}`;
 $('#notify-save')?.addEventListener('click',async e=>{const b=e.currentTarget;b.disabled=true;try{const answers=$('#notify-answers').checked,feedback=$('#notify-feedback').checked,events=$('#notify-events').checked;if(answers||feedback||events){if(!('Notification'in window)||!('PushManager'in window))throw Error('Questo browser non supporta gli avvisi. Su iPhone installa prima l’app nella schermata Home.');const permission=await Notification.requestPermission();if(permission!=='granted'){await api('later',{});throw Error('Avvisi non attivati. Nessuna nuova richiesta automatica per 7 giorni.')}const reg=await navigator.serviceWorker.ready;await reg.update();const candidate=reg.installing||reg.waiting;if(candidate){await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('Riapri l’app per completare l’aggiornamento.')),15000);const check=()=>{if(candidate.state==='installed')candidate.postMessage({type:'ACTIVATE_SCHOOL_PUSH'});if(candidate.state==='activated'){clearTimeout(timeout);resolve()}};candidate.addEventListener('statechange',check);check()})}const bytes=Uint8Array.from(atob(c.publicKey.replaceAll('-','+').replaceAll('_','/')),x=>x.charCodeAt(0));const sub=await reg.pushManager.getSubscription()||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes});await api('subscribe',{endpoint:sub.endpoint,answers});await api('feedback',{enabled:feedback});await api('events',{enabled:events})}else{await api('feedback',{enabled:false});await api('events',{enabled:false});await api('disable',{});const reg=await navigator.serviceWorker.getRegistration();await (await reg?.pushManager.getSubscription())?.unsubscribe()}$('#notify-status').textContent='Preferenze salvate.'}catch(err){$('#notify-status').textContent=err.message}finally{b.disabled=false}});
 }catch{host.innerHTML=`<h2>I tuoi avvisi</h2>${notificationPolicyHTML()}<p>Preferenze non disponibili adesso. Riprova quando torna la connessione.</p><a href="#insieme">Leggi le risposte alle tue domande</a>`}}
export function installNotificationOffer(){let busy=false;window.addEventListener('sky-published',async()=>{if(busy||$('#notification-offer'))return;busy=true;try{const c=await api('config');if(!c.eligible||!c.available||c.enabled||c.feedbackEnabled||c.eventsEnabled||c.later>Date.now())return;const box=document.createElement('aside');box.id='notification-offer';box.className='sky-success';box.setAttribute('aria-live','polite');box.innerHTML=`<h2>Ti avvisiamo solo quando serve.</h2><p>Scegli risposte alle tue domande, conferme alle tue segnalazioni e cambiamenti dei tuoi eventi.</p>${notificationPolicyHTML()}<a href="#profilo" id="notification-choose">Scegli gli avvisi</a> <button id="notification-later">Non ora</button>`;$('#main')?.before(box);$('#notification-choose').onclick=()=>box.remove();$('#notification-later').onclick=async()=>{try{await api('later',{});box.remove()}catch{box.querySelector('p').textContent='Non riesco a salvare la scelta. Riprova.'}}}catch{}finally{busy=false}})}
